	}

	return summary, nil
}"},{"rank":4,"score":31.701,"file_path":"cmd/entire/cli/checkpoint/persistent.go","start_line":2499,"end_line":2555,"focus_line":2507,"snippet_start_line":2507,"snippet_end_line":2555,"symbol_start_line":2507,"symbol_end_line":2555,"language":"Go","kind":"function","symbol_id":"local/btw_codex:Go:cmd/entire/cli/checkpoint/persistent.go:function:createRedactedBlobFromFile","symbol_name":"createRedactedBlobFromFile","qualified_name":"createRedactedBlobFromFile","signature":"func createRedactedBlobFromFile(ctx context.Context, repo *git.Repository, cache *redactCache, root *os.Root, name, treePath string) (plumbing.Hash, filemode.FileMode, error)","signals":["path","body","symbol-name","graph:callers","complete-symbol"],"snippet":"func createRedactedBlobFromFile(ctx context.Context, repo *git.Repository, cache *redactCache, root *os.Root, name, treePath string) (plumbing.Hash, filemode.FileMode, error) {
	info, err := osroot.LstatNoSymlinks(root, name)
	if err != nil {
		return plumbing.ZeroHash, 0, fmt.Errorf("failed to stat file: %w", err)
	}

	mode := filemode.Regular
	if info.Mode()&0o111 != 0 {
		mode = filemode.Executable
	}

	content, err := entiredir.ReadFile(root, name)
	if err != nil {
		return plumbing.ZeroHash, 0, fmt.Errorf("failed to read file: %w", err)
	}

	// Skip redaction for binary files — they can't contain text secrets and
	// running string replacement on them would corrupt the data.
	isBin, binErr := binary.IsBinary(bytes.NewReader(content))
	if binErr != nil || isBin {
		hash, err := CreateBlobFromContent(repo, content)
		if err != nil {
			return plumbing.ZeroHash, 0, fmt.Errorf("failed to create blob: %w", err)
		}
		return hash, mode, nil
	}

	// Large append-only transcripts reuse the prefix redacted for the previous
	// checkpoint and redact only what was appended; see redact_cache.go. Output is
